    # different color encodes one cell; mixed/non-marker squares are tile fill.
    line_color = Counter(grid[r][c] for r in rows for c in cols).most_common(1)[0][0]
    out = []
    for r0, r1 in zip(rows, rows[1:]):
        row = []
