            row.append(corners[0] if corners[0] != line_color and len(set(corners)) == 1 else tile)
        if not out or row != out[-1]:
            out.append(row)
    # Remove unmarked outside margins, keeping blank cells within the image.
    while out and all(v == tile for v in out[0]):
